const keys=new Set(),pointers=new Map();let yaw=0,pitch=.68,distance=innerWidth<700?29:36,drag=false,lastX=0,lastY=0,pinchDistance=0,joy={x:0,y:0},touchId=null,toastTimer,riverToast=false;
