function interact(){if(isPaused()||state.mixerRide)return;if(state.game){stopCatch(state);toast(state.event);canvas.focus({preventScroll:true});return;}const n=nearby(state);if(!n){toast('Walk up to the oven, cake studio, or tasting counter.');return;}if(n.id==='treats'){if(taste(state)){burst(state.x,2,state.z);toast(state.event+(state.tasted===5?' Taste Tester badge earned!':''));canvas.focus({preventScroll:true});}}else if(n.id==='oven'){clearControls();if(startCatch(state)){yaw=0;toast(state.event);canvas.focus({preventScroll:true});}}else{const order=openOrder(state);if(!order)return;clearControls();pickedFlavor=pickedTopping=-1;refreshChoices();$('#order-text').textContent=`Today’s order: ${FLAVORS[order.flavor].name.toLowerCase()} frosting + ${TOPPINGS[order.topping].toLowerCase()}.`;$('#cake-feedback').textContent='Match the order to earn your cake badge.';$('#serve').hidden=false;$('#cake-done').hidden=true;$('#cake-dialog').querySelectorAll('.choice-row button').forEach(b=>b.disabled=false);$('#cake-dialog').showModal();}}
$('#serve').onclick=()=>{if(pickedFlavor<0||pickedTopping<0){$('#cake-feedback').textContent='Choose one frosting and one topping first.';return;}const result=serveCake(state,pickedFlavor,pickedTopping);if(result==='retry')$('#cake-feedback').textContent='A delicious idea! Check the order above and try those ingredients.';if(result==='correct'){$('#cake-feedback').textContent='Perfect! Cake Artist badge earned. Your cake is on display!';$('#serve').hidden=true;$('#cake-done').hidden=false;$('#cake-dialog').querySelectorAll('.choice-row button').forEach(b=>b.disabled=true);celebrateCake=true;$('#cake-done').focus();}};
$('#close-cake').onclick=$('#cake-done').onclick=()=>$('#cake-dialog').close();$('#cake-dialog').addEventListener('close',()=>{state.order=null;clearControls();canvas.focus({preventScroll:true});if(celebrateCake){burst(10,5,0);toast('Order up! Your masterpiece is on display.');celebrateCake=false;}});
